using System;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ApothecarysSecretOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/ApothecarysSecretOmenData")]
public class ApothecarysSecretOmenData : OnSpecificDiceTierOmenData
{
	[SerializeField]
	private int turnToChangeAction = 6;

	private OmenInstance omenInstance;

	private Action apothecarysSecretOmenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		this.omenInstance = omenInstance;
		apothecarysSecretOmenAction = delegate
		{
			if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunStats.CurrentBattle.BattleTurnCounter == turnToChangeAction)
			{
				omenInstance.EnqueueOmenFeedbackAndPlay();
			}
		};
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.StartOfTurnOmenCheckActivateActions.Add(apothecarysSecretOmenAction);
		base.Initialize(omenInstance);
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.StartOfTurnOmenCheckActivateActions.Remove(apothecarysSecretOmenAction);
		base.OmenRemoved();
	}

	protected override void OmenLogicActiveOmen(int actionAmount, GameObject target = null, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE)
	{
		omenInstance.EnqueueOmenFeedbackAndPlay();
		if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunStats.CurrentBattle.BattleTurnCounter < turnToChangeAction)
		{
			OmenLogic.ActivateOmen(BattleAction, actionAmount, null, null);
		}
		else
		{
			secondOmenLogicActionFace.ActivateOmen();
		}
	}

	public override string OmenConvertedDescription()
	{
		string localizedNeutralDie = base.localizationManager.GetLocalizedNeutralDie();
		string text = Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedWheneverYouPlayA(), localizedNeutralDie);
		string arg = text + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + GetOmenConvertedDescriptionBattleAction().LowercaseFirst();
		string arg2 = text + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + secondOmenLogicActionFace.GetActionDescription().LowercaseFirst();
		string text2 = Smart.Format(GetOmenRawLocalizedDescription(), turnToChangeAction, arg, arg2);
		if (corruptionNotIncreasedByCorruptionModifier)
		{
			text2 = text2 + "\n" + base.localizationManager.GetLocalizedCorruptionNotIncreasedByCorruptionModifier();
		}
		return CheckAppendCounterKeptBetweenBattlesDescription(text2);
	}
}
